"const fs = require('fs');
const html = fs.readFileSync('c:\\Users\\rahat\\OneDrive\\Desktop\\Rahat\\UCSD\\Fall 26\\CSE216\\results\\gemini\\L3\\run-07\\site\\index.html', 'utf8');

const buttons = [...html.matchAll(/<button([^>]*)>(.*?)<\/button>/gis)];
console.log('Total buttons found in HTML:', buttons.length);

let buttonErrors = 0;
buttons.forEach(btn => {
  const attrs = btn[1];
  const inner = btn[2].replace(/<[^>]+>/g, '').trim();
  const ariaLabelMatch = attrs.match(/aria-label=["']([^"']+)["']/i);
  const ariaLabel = ariaLabelMatch ? ariaLabelMatch[1] : null;

  if (!inner && !ariaLabel) {
    console.warn('Button with no visible text and no aria-label:', btn[0]);
    buttonErrors++;
  } else {
    // If has visible text and aria-label, check Rule 29: aria-label starts with visible text
    if (inner && ariaLabel) {
      if (!ariaLabel.toLowerCase().startsWith(inner.toLowerCase())) {
        console.warn(`Rule 29 warning: Button visible "${inner}" does not start aria-label "${ariaLabel}"`);
      }
    }
  }
});

if (buttonErrors === 0) {
  console.log('PASS: All static buttons have accessible names!');
}
