"const fs = require('fs');
const scriptContent = fs.readFileSync('c:\\Users\\rahat\\OneDrive\\Desktop\\Rahat\\UCSD\\Fall 26\\CSE216\\results\\gemini\\L3\\run-07\\site\\script.js', 'utf8');

